  "webLanding.lede": "பில்கள், கடன் வழங்குதல் மற்றும் உங்கள் பெரோவோ ஸ்கோரைக் கண்காணிக்கவும் — உங்கள் மொபைலில், உங்கள் சாதனத்தில் உங்கள் தரவு தங்கியிருக்கும். தொடங்குவதற்கு Android பயன்பாட்டை நிறுவவும்.",
