  "webLanding.feature.local.desc": "உங்கள் சாதனத்தில் ஆஃப்லைனில் வேலை செய்கிறது. நீங்கள் உள்நுழையும்போது விருப்ப மேகக்கணி காப்புப்பிரதி.",
  "webLanding.feature.languages.title": "23 மொழிகள்",
  "webLanding.feature.languages.desc": "இந்திய மொழிகளில் முழு பயன்பாடு — அமைப்புகளில் உங்களுடையதைத் தேர்ந்தெடுக்கவும்.",
  "webLanding.feature.insights.title": "ஸ்மார்ட் நுண்ணறிவு",
  "webLanding.feature.insights.desc": "சம்பளம் வாங்குபவர்கள் மற்றும் குடும்ப குடும்பங்களுக்கான பகுப்பாய்வுகள்.",
  "webLanding.downloadTitle": "Android க்கு பதிவிறக்கவும்",
  "webLanding.downloadBody": "இணையதளம் தகவலுக்காக மட்டுமே. உங்கள் சாதனத்தில் இயங்கும் பெரோவோ - பில்கள், மதிப்பெண்கள் மற்றும் காப்புப்பிரதிகளைப் பயன்படுத்த பயன்பாட்டை நிறுவவும்.",
  "webLanding.downloadButton": "Android APK ஐப் பதிவிறக்கவும்",
  "webLanding.downloadHint": "Android நிறுவலைத் தடுத்தால், உங்கள் உலாவி அல்லது கோப்பு மேலாளருக்கான \"தெரியாத பயன்பாடுகளை நிறுவு\" என்பதை இயக்கவும். டெவலப்பர் உருவாக்கம் — இதுவரை Play Store இல் இருந்து வரவில்லை.",
  "webLanding.versionsTitle": "பதிப்பைத் தேர்ந்தெடு (சோதனை)",
  "webLanding.versionsNote": "பதிவிறக்கங்கள் மற்றும் பயன்பாட்டில் புதுப்பிப்புகளைச் சோதிப்பதற்கான தற்காலிக பட்டியல். பழைய APKஐ நிறுவி, புதிய உருவாக்கம் நேரலையில் வந்த பிறகு, அமைப்புகளில் அப்டேட் ஆப்ஸைப் பயன்படுத்தவும்.",
