  "kyc.digilocker.placeholder": "DigiLocker தானியங்கு நிரப்பல் உங்கள் சரிபார்க்கப்பட்ட ஆதார் பெயர் மற்றும் முகவரியை ஒரே தட்டலில் பெற உதவுகிறது. DigiLocker API அணுகலுக்கு அரசு அனுமதி தேவை. இப்போதைக்கு, விவரங்களை கைமுறையாக நிரப்பவும்.",
