  "lending.stamp.footer": "முத்திரை இல்லாமல்: ஆவணத்தை நீதிமன்றத்தில் இன்னும் பயன்படுத்தலாம் ஆனால் முத்திரை கட்டணம் + அபராதம் தாக்கல் செய்வதற்கு முன் செலுத்தப்பட வேண்டும்.",
  "lending.stamp.courtReady": "முத்திரைத் தீர்வை - அதை நீதிமன்றத்திற்குத் தயார் செய்யுங்கள்",
  "lending.stamp.courtWarn": "முத்திரைத் தீர்வை இல்லாமல், இந்த ஆவணத்தை தாக்கல் செய்வதற்கு முன் நீதிமன்றத்தால் பறிமுதல் செய்யலாம். பெரும்பாலான உறுதிமொழிக் குறிப்புகளுக்கு முத்திரைத் தொகையில் ₹1–5 தேவைப்படுகிறது.",
  "lending.stamp.stateRow": "{state}: {amount}",
