  "lending.stamp.findVendor": "எனக்கு அருகிலுள்ள முத்திரை விற்பனையாளரைக் கண்டறியவும் →",
  "lending.stamp.printHint": "நீங்கள் பதிவிறக்கம் செய்த PDF ஐ முத்திரைத் தாளில் அச்சிடவும் அல்லது SHCIL இலிருந்து மின் முத்திரையைப் பெற்று மின்-முத்திரைத் தாளில் அச்சிடவும்.",
