  "lending.flow.readyToShare": "உங்கள் ஒப்பந்தம் தயாராக உள்ளது. மறுபரிசீலனைக்காக கடன் வாங்குபவருடன் பகிர்ந்து கொள்ளுங்கள், பின்னர் சட்டப்பூர்வ செல்லுபடியாக்கத்திற்கான ஆதார் eSign ஐ முடிக்கவும்.",
  "lending.flow.shareWhatsapp": "WhatsApp → இல் பங்கு ஒப்பந்தம்",
