  "lending.flow.dealWhatsapp": "WhatsApp → இல் ஒப்பந்த உறுதிப்படுத்தலை அனுப்பவும்",
  "lending.flow.overdueTitle": "கட்டணம் தாமதமானது - பழைய நிலுவைத் தேதியிலிருந்து {days} நாட்கள்",
