  "notifications.reminder.upcoming": "வரவிருக்கிறது: {name}",
  "notifications.reminder.lendingOverdue": "கடன் தாமதம்: {name}",
  "notifications.reminder.lendingDue": "கடன் நிலுவைத் தொகை: {name}",
  "notifications.reminder.subEnd": "{name} விரைவில் முடிவடைகிறது — நீங்கள் புதுப்பிக்க விரும்பவில்லை என்றால், தானாக செலுத்துவதை ரத்துசெய்யவும்.",
  "notifications.reminder.lumpyHorizon": "{name} ({repeatType}) ~{months} மாதத்தில் நிலுவையில் உள்ளது — அந்த மாதத்திற்கு முன் பணத்தை ஒதுக்குங்கள்.",
  "notifications.reminder.suffix.amountToday": "₹{amount} இன்று நிலுவையில் உள்ளது",
  "notifications.reminder.suffix.amountTodayWithCash": "இன்று நிலுவையில் உள்ள ₹{amount} · ~₹{afterPay} பிறகு மீதமுள்ளது",
  "notifications.reminder.suffix.amountTodayExceeds": "இன்று நிலுவையில் உள்ள ₹{amount} · இலவசப் பணத்தை விட அதிகமாக இருக்கலாம்",
