  "notifications.reminder.suffix.amountInDaysExceeds": "{days}d இல் செலுத்த வேண்டிய ₹{amount} இலவசப் பணத்தை விட அதிகமாக இருக்கலாம்",
  "notifications.reminder.osBody": "{name}: ₹{amount}",
  "backup.fileTitle": "கோப்பு காப்புப்பிரதி",
  "backup.fileSubtitle": "இந்தச் சாதனத்தில் JSON கோப்பை ஏற்றுமதி செய்யவும் அல்லது இறக்குமதி செய்யவும். மேலே உள்ள கணக்கு காப்புப்பிரதியில் Supabase இலிருந்து மீட்டெடுக்கவும்.",
  "backup.exportJson": "JSON காப்புப்பிரதியை ஏற்றுமதி செய்யவும்",
  "backup.exportJsonHint": "பில்கள், கடன் வழங்குதல், இலக்குகள் மற்றும் அமைப்புகளை ஒரு கோப்பில் சேமிக்கவும்",
  "backup.exportOptionsKicker": "Export options",
  "backup.importJson": "இறக்குமதி JSON",
  "backup.importMerge": "ஒன்றிணைக்கவும் - ஏற்கனவே வைத்திருக்கவும், புதியவற்றைச் சேர்க்கவும் (நகல் ஐடிகளைத் தவிர்க்கவும்)",
  "backup.importReplace": "மாற்றவும் - கோப்பிலிருந்து பட்டியல்களை மேலெழுதவும்",
  "backup.preview": "முன்னோட்டம்: {bills} பில்கள், {lending} கடன், {goals} இலக்குகள்{settings}.",
  "backup.previewSettings": ", அமைப்புகளை உள்ளடக்கியது",
  "backup.confirmImport": "இறக்குமதியை உறுதிப்படுத்தவும்",
  "backup.imported": "இறக்குமதி: {bills} பில்கள், {lending} கடன், {goals} இலக்குகள் ({mode}).",
  "backup.readError": "JSON ஐப் படிக்க முடியவில்லை. Perovo ஏற்றுமதி கோப்பைப் பயன்படுத்தவும்.",
  "backup.importFailed": "இறக்குமதி தோல்வியடைந்தது",
  "backup.deleteTitle": "எல்லா தரவையும் நீக்கு",
  "backup.deleteSubtitle": "இந்தச் சாதனத்தில் உள்ள அனைத்து பில்கள், கடன் வழங்குதல் மற்றும் அமைப்புகளை நிரந்தரமாக அழிக்கவும்{cloud}. இதை செயல்தவிர்க்க முடியாது.",
  "backup.deleteCloud": "மற்றும் உங்கள் கிளவுட் சுயவிவரம்",
  "backup.deleteAll": "எல்லா தரவையும் நீக்கு",
  "backup.deleteModalTitle": "எல்லா தரவையும் நீக்கவா?",
  "backup.deleteModalBody": "இது அனைத்து உள்ளூர் தரவையும் நீக்குகிறது மற்றும் {cloud} உங்கள் பதிவுகள் தேவைப்பட்டால் முதலில் காப்புப்பிரதியை ஏற்றுமதி செய்யவும்.",
  "backup.deleteCloudModal": "உங்கள் Supabase சுயவிவரத்தை நீக்குகிறது.",
  "backup.deleteSignout": "உங்களை மேகக்கணி ஒத்திசைவிலிருந்து வெளியேற்றுகிறது.",
  "backup.deleteConfirm": "ஆம், அனைத்தையும் நீக்கவும்",
  "backup.deleteFailed": "கணக்குத் தரவை நீக்க முடியவில்லை.",
  "backup.annualReport": "ஆண்டு அறிக்கை",
  "backup.annualReportHint": "ஆண்டு சுருக்கம் - அழுத்தம், துணை, உயிர்வாழ்வு (Pro).",
  "backup.annualReportHintPro": "விளக்கப்படங்கள் மற்றும் சந்தா தணிக்கையுடன் முழு HTML/PDF-பாணி அறிக்கை.",
  "backup.annualReportHintFree": "எளிய உரை சுருக்கம் — முழு HTML அறிக்கைக்காக Pro க்கு மேம்படுத்தவும்.",
  "tier.limit.lendingTitle": "கடன் வரம்பை எட்டிவிட்டது",
  "tier.pro.member": "Pro member",
  "tier.power.member": "Power member",
