  "add.form.chitRepeatNote": "சிட் முடியும் வரை மாதந்தோறும் திரும்பத் திரும்ப நடக்கும். ஒரு புதிய மாதம் தொடங்கும் போது, ​​உங்கள் நிலுவைத் தொகை குறைந்த தவணைக்கு புதுப்பிக்கப்படும் - அதை நீங்களே மாற்ற வேண்டாம்.",
