  "plans.fileBackupLink": "கோப்பு காப்புப்பிரதி → காப்புப்பிரதி & தரவு",
  "plans.signInRequired": "Razorpay மூலம் பணம் செலுத்த Profile இலிருந்து உள்நுழையவும்.",
  "plans.paySuccess": "உங்கள் திட்டம் இப்போது {tier}. சந்தா செலுத்தியதற்கு நன்றி.",
