  "plans.payFailed": "பணம் செலுத்த முடியவில்லை. மீண்டும் முயற்சிக்கவும்.",
  "plans.orderFailed": "செக் அவுட் தொடங்க முடியவில்லை. வைஃபையைச் சரிபார்த்து மீண்டும் முயற்சிக்கவும் அல்லது ஆதரவைத் தொடர்புகொள்ளவும்.",
  "plans.simulateSuccess": "[சோதனை] உருவகப்படுத்தப்பட்ட கட்டணம் முடிந்தது. உங்கள் திட்டம் இப்போது {tier}.",
  "plans.simulateFailed": "உருவகப்படுத்துதல் தோல்வியடைந்தது.",
  "plans.simulateHint": "உருவகப்படுத்துதல் முறை: Razorpay செக்அவுட் இல்லை. VITE_RAZORPAY_KEY_ID=rzp_test_…ஐ .env இல் சேர்த்து, சோதனைக் கட்டணங்களைப் பயன்படுத்த, டெவ்வை மறுதொடக்கம் செய்யவும்.",
  "plans.razorpayTestHint": "Razorpay சோதனை முறை — UPI success@razorpay அல்லது கார்டு 5267 3181 8797 5449 (ஏதேனும் காலாவதியாகும்/CVV) பயன்படுத்தவும்.",
  "plans.razorpayLiveHint": "நேரலை Razorpay செக்அவுட் — உண்மையான கட்டணங்கள் பொருந்தும்.",
