  "proGate.proHint": "ஒரு Pro சந்தா மேம்பட்ட கருவிகள், அறிக்கைகள் மற்றும் நீட்டிக்கப்பட்ட பகுப்பாய்வு ஆகியவற்றைத் திறக்கும்.",
