  "emergency.tier.critical": "அவசரகால இருப்பு உங்கள் கடமைகளுக்கு மிகவும் குறைவாக பரிந்துரைக்கப்படுகிறது.",
  "emergency.tier.building": "கையிருப்பு நடந்து கொண்டிருக்கிறது - 3-6 மாதச் செலவுகளைத் தொடரவும்.",
  "emergency.tier.almost": "நீங்கள் ஆரோக்கியமான அவசரநிலை இடையகத்திற்கு அருகில் உள்ளீர்கள்.",
  "emergency.tier.on_track": "தற்போதைய அழுத்தத்திற்கு அவசர இருப்பு ஆரோக்கியமாகத் தெரிகிறது.",
  "emergency.insight.lowCover": "இருப்பு {months} மாத பில்களை மட்டுமே உள்ளடக்கும் - இந்த இடையகத்தை உருவாக்குவதற்கு முன்னுரிமை கொடுங்கள்.",
  "emergency.insight.topUp": "சுமார் ₹{amount}/மாதம் ~{months} மாதங்களில் இலக்கை அடைகிறது.",
  "emergency.insight.funded": "இருப்பு {months} மாதங்கள் - வருமானம் அதிகரிக்கும் போது இந்த அளவைப் பராமரிக்கவும்.",
  "pressure.hint.safe": "போதுமான அளவு உள்ளது - இருப்புக்களை உருவாக்குவதைத் தொடரவும்.",
  "pressure.hint.moderate": "நிர்வகிக்கக்கூடியது, ஆனால் புதிய EMIகள் மற்றும் சந்தாக்களை கண்காணிக்கவும்.",
  "pressure.hint.constrained": "பில்கள் வருவாயில் பெரும் பங்கைப் பயன்படுத்துகின்றன - நிலுவைத் தொகைகளுக்கு முன்னுரிமை அளிக்கின்றன.",
  "pressure.hint.elevated": "எதிர்பாராத செலவுகளுக்கு வரையறுக்கப்பட்ட இடையகம் - புதிய நீண்ட கடமைகளை ஒத்திவைத்தல்.",
  "pressure.hint.critical": "அழுத்தம் அதிகமாக உள்ளது - காலாவதியான பொருட்கள் மற்றும் அத்தியாவசியங்களை முதலில் கவனிக்கவும்.",
  "pressure.trend.rising": "சமீபத்திய மாதங்களில் அழுத்தம் சுமார் {delta} புள்ளிகள் உயர்ந்துள்ளது - கடமைகள் குவிந்து இருக்கலாம்.",
  "pressure.trend.easing": "சமீபத்தில் {delta} புள்ளிகள் அழுத்தம் குறைந்துள்ளது - நிதி அழுத்தம் குறைந்து வருகிறது.",
  "pressure.forecast.monthNamed": "{month} அதிக கடமைகளைக் கொண்டிருக்கலாம் — சுமார் {count} பில்(கள்) நிலுவையில் (~{amount}).",
