  "wealthDetail.property.sellNegativeReturn": "பணவீக்கத்திற்குப் பிறகு உண்மையான வருமானம் எதிர்மறையாக இருக்கும். பணப்புழக்கம் தேவைப்பட்டால், விற்க இது ஒரு நியாயமான நேரம் - 5+ ஆண்டுகளுக்குப் பிறகு நீடித்த குறைவான செயல்திறன்.",
