  "wealthDetail.gold.makingCharges": "உடல் அலங்காரத் தங்கம், கொள்முதல் விலையில் உட்பொதிக்கப்பட்ட ~{pct}% செய்யும் கட்டணங்கள் (~{amount}) அடங்கும். மறுவிற்பனையில் இந்தக் கட்டணங்கள் வசூலிக்கப்படாது - தங்கத்தின் உள்ளடக்கம் மட்டுமே திரவ மதிப்பைக் கொண்டுள்ளது.",
