  "wealthDetail.gold.sgbNote": "இறையாண்மை தங்கப் பத்திரங்கள் தங்கத்தின் மீது 2.5% வருடாந்திர வட்டி மற்றும் விலை ஏற்றம், கட்டணம் எதுவும் இல்லை, மேலும் 8 ஆண்டுகளுக்குப் பிறகு LTCG இலிருந்து விலக்கு அளிக்கப்படுகிறது. புதிய தங்கம் வாங்குதல்களுக்கு, SGB அல்லது Gold ETF பொதுவாக உடல் அலங்கார தங்கத்தை விட திறமையானது.",
  "wealthDetail.gold.holdWaitDetail": "நீங்கள் {years} ஆண்டுகள் வைத்திருக்கிறீர்கள். இப்போது விற்பனை செய்வது உங்கள் ஸ்லாப் விகிதத்தில் ({slab}%) குறுகிய கால வரியை ஈர்க்கிறது. {ltcgYears} ஆண்டுகள் வரை வைத்திருப்பது ~₹{taxSaving} வரியைச் சேமிக்கிறது.",
  "wealthDetail.gold.holdGoodDetail": "தங்கம் {realReturn}% பணவீக்கத்தை முறியடிக்கிறது. தொடர்ந்து வைத்திருங்கள் - நிச்சயமற்ற நிலையில் தங்கம் ஒரு ஹெட்ஜ் ஆக சிறப்பாக செயல்படுகிறது.",
  "wealthDetail.gold.holdReviewDetail": "உண்மையான வருவாய் எதிர்மறையானது ({realReturn}%). தங்கம் பணவீக்கத்துடன் ஒத்துப்போகவில்லை - உங்கள் இலக்குகளுக்கு இந்த ஒதுக்கீடு சரியானதா என்பதைக் கவனியுங்கள்.",
  "wealthDetail.gold.holdModerateDetail": "தங்கம் பணவீக்கத்திற்கு எதிராக மதிப்பை பராமரிக்கிறது. ஹெட்ஜ் போல நல்லது - பொதுவாக போர்ட்ஃபோலியோவில் 5-10%.",
