  "wealthDetail.fd.debtMfNote": "டெப்ட் மியூச்சுவல் ஃபண்டுகள் (குறுகிய கால அல்லது கார்ப்பரேட் பாண்ட் ஃபண்டுகள் போன்றவை) ஒரே மாதிரியான வருமானத்தை வழங்குகின்றன, ஆனால் மீட்பின் உங்கள் ஸ்லாப் விகிதத்தில் வரி விதிக்கப்படும் - FD போன்ற வருடாந்திர TDS இல்லை. அவை சிறந்த பணப்புழக்கத்தையும் வழங்குகின்றன (T+1 மீட்பு vs FD முன்கூட்டியே திரும்பப் பெறுதல் அபராதம்).",
