  "wealthDetail.fd.holdGoodDetail": "FD மூலதன பாதுகாப்பு மற்றும் கணிக்கக்கூடிய வருமானத்தை வழங்குகிறது. அவசர நிதி அல்லது குறுகிய கால இலக்குகளுக்கு (3 ஆண்டுகளுக்கு கீழ்) மிகவும் பொருத்தமானது.",
  "wealthDetail.fd.holdReviewDetail": "வரி மற்றும் பணவீக்கத்திற்குப் பிறகு, இந்த FD ஆண்டுக்கு {realReturn}% உண்மையான வாங்கும் திறனை இழக்கிறது. இந்த FD முதிர்ச்சியடையும் போது கடன் பரஸ்பர நிதிகள் (அதிக வரி-திறன்) அல்லது I-பண்டுகளுக்கு பகுதி மறுஒதுக்கீட்டைக் கருத்தில் கொள்ளுங்கள்.",
  "wealthDetail.fd.holdMaturitySoonDetail": "இந்த FD {months} மாதங்களில் முதிர்ச்சியடைகிறது. புதுப்பித்தல் உத்தியை இப்போதே முடிவு செய்யுங்கள் - தானாக புதுப்பித்தல் உங்களை குறைந்த விகிதத்தில் அடைக்கலாம்.",
