  "wealthDetail.vehicle.depreciationNote": "வாகனங்கள் சொத்து மதிப்பைக் குறைக்கின்றன - பொதுவாக 1 ஆம் ஆண்டில் 15-20%, அதன் பிறகு ஆண்டுதோறும் 10-15%. நிகர மதிப்பைக் கணக்கிடும் போது இதை மனதில் கொள்ளுங்கள் - உண்மையான மறுவிற்பனை மதிப்பு மேலே மதிப்பிடப்பட்ட எண்ணிக்கையை விட குறைவாக இருக்கலாம்.",
